import fs from "fs"; import {execSync} from "child_process";
const files = execSync('git ls-files "src/**/*.ts" "src/**/*.html"',{encoding:"utf8"}).trim().split("\n");
let total=0;
for (const f of files) {
  const s = fs.readFileSync(f,"utf8"); let out="", i=0, n=0;
  const re=/<app-(fancy-pill|status-pill)(?=[\s>\/])/g; let m;
  while ((m=re.exec(s))) {
    let j=m.index+m[0].length, q=null, seg="";
    out+=s.slice(i,j);
    for (; j<s.length; j++) {
      const c=s[j];
      if (q) { if (c===q) q=null; out+=c; continue; }
      if (c==='"'||c==="'") { q=c; out+=c; continue; }
      if (c==='>') break;
      if (s.startsWith("disableTooltip",j) && /[\s\[]/.test(s[j-1]) && /[\s\]=>\/]/.test(s[j+14])) { out+="hideHint"; j+=13; n++; continue; }
      out+=c;
    }
    i=j; re.lastIndex=j;
  }
  out+=s.slice(i);
  if (n) { fs.writeFileSync(f,out); total+=n; }
}
console.log(total);
EOF
