cat > /tmp/ren2.mjs <<'EOF'
import fs from "fs"; import {execSync} from "child_process";
const files = execSync('git ls-files "src/**/*.ts" "src/**/*.html"',{encoding:"utf8"}).trim().split("\n").filter(f=>!/lib\/(card|pill-legacy)\.component/.test(f));
let total=0;
for (const f of files) {
  const s = fs.readFileSync(f,"utf8");
  let o = s.replace(/([\w)?]*)\.disableTooltip\(\)/g,(m,p)=>/^(card\(\)\??|summary|card)$/.test(p)?m:(total++,p+".hideHint()"));
  if (/lib\/(fancy|status)-pill/.test(f)) o=o.replace(/!disableTooltip\(\)/,()=>(total++,"!hideHint()"));
  if (/pill-tray/.test(f)) o=o.replace(/pill\.setInput\("disableTooltip"/g,()=>(total++,'pill.setInput("hideHint"'));
  if (o!==s) fs.writeFileSync(f,o);
}
let c=fs.readFileSync("src/styles.css","utf8");
c=c.replace(/app-(pill|fancy-pill|status-pill)\[disableTooltip\]/g,(m,p)=>(total++,`app-${p}[hideHint]`));
fs.writeFileSync("src/styles.css",c);
console.log(total);
EOF
node /tmp/ren2.mjs; npx ngc -p tsconfig.json; echo exit $?
git grep -n "disableTooltip()" ; git grep -nE "styles?:|styleUrl" -- src | head; git ls-files | grep -vE "^src/app/features|^.claude" ; git diff --stat | tail -1

